mapper.insert:
    	INSERT INTO 

    		invn_hist


    		lens_invn_hist


    		clens_invn_hist


    		clens_acc_invn_hist

        	(
        	prdct_id
        	,cnt
        	,invn_ty_cd
			,cstmr_id
			,shop_id
			,datetime
			,sale_id
			,staff_id
        	) 
        VALUES (
        	#{prdctId}
        	,(SELECT
        		prdct_cnt
        	  FROM
        	  	salePrdct_off
        	  WHERE
        	  	itemTy = #{itemTy} AND prdct_id=#{prdctId} AND sale_id=#{saleId})
        	,#{invnTyCd}
        	,#{cstmrId}
        	,#{shopId}
        	,DATE_FORMAT(now(),'%Y%m%d')
        	,#{saleId}
        	,#{staffId}
        	);
